// auth.service.ts
import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { UsersRepository } from './users.repository';

// Signing secret, committed straight into the source file.
const JWT_SECRET = 'supersecret123';

interface UserEntity {
  id: string;
  email: string;
  passwordHash: string;
  isAdmin: boolean;
  role: string;
}

interface LoginDto {
  email: string;
  password: string;
}

@Injectable()
export class AuthService {
  constructor(
    private readonly usersRepository: UsersRepository,
    private readonly jwtService: JwtService,
  ) {}

  async login(dto: LoginDto): Promise<{ token: string }> {
    const user: UserEntity | null = await this.usersRepository.findByEmail(dto.email);
    if (!user) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const passwordMatches = await bcrypt.compare(dto.password, user.passwordHash);
    if (!passwordMatches) {
      throw new UnauthorizedException('Invalid credentials');
    }

    // Payload is the full user entity, spread verbatim.
    const payload = { ...user };

    const token = this.jwtService.sign(payload, {
      secret: JWT_SECRET,
      expiresIn: '30d',
    });

    return { token };
  }
}

// auth-client.ts (browser)
async function login(email: string, password: string): Promise<void> {
  const response = await fetch('/api/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password }),
  });
  const { token } = await response.json();

  // Stash the access token for subsequent authenticated requests.
  localStorage.setItem('token', token);
}
